"""The site's IPAM into NetBox from the address plan (Insular ADR-0171 point 4): reads the plan generated by
tools/netbox_seed.py (seed-site.json, checked current by a test) and creates, as pipeline-dcim, what NetBox lacks:
the site's tag, its prefixes (pod and service ranges as containers, never per address) and its per-address records.
Idempotent; never changes or deletes what exists (a difference is drift, reported by the reconciler). Standard library
only. Usage: python3 /app/seed.py
"""
from __future__ import annotations

import ipaddress
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

NB = os.environ.get("NETBOX_URL", "http://netbox.vdh-netbox.svc.cluster.local:8080")
PLAN = os.environ.get("SEED_PLAN", "/app/seed-site.json")
TOKEN_FILE = os.environ.get("TOKEN_FILE", "/token/authorization")


def nb(method: str, path: str, body: dict | None = None) -> tuple[int, dict]:
    auth = open(TOKEN_FILE, encoding="utf-8").read().strip()
    req = urllib.request.Request(NB + path, method=method, data=None if body is None else json.dumps(body).encode(),
                                 headers={"Authorization": auth, "Accept": "application/json", "Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        return e.code, {}


def ensure(path: str, query: dict, body: dict) -> str:
    status, found = nb("GET", f"{path}?{urllib.parse.urlencode(query)}")
    if status != 200:
        raise RuntimeError(f"{path}: NetBox answered {status}")
    if found.get("count"):
        return "present"
    status, _ = nb("POST", path, body)
    if status != 201:
        raise RuntimeError(f"{path}: create refused ({status})")
    return "created"


def main() -> int:
    plan = json.load(open(PLAN, encoding="utf-8"))
    slug = f"vdh-{plan['site']}"
    tag = [{"slug": slug}]
    counts = {"created": 0, "present": 0}
    counts[ensure("/api/extras/tags/", {"slug": slug}, {"name": slug, "slug": slug, "color": "607d8b",
                                                         "description": "seeded from the address plan (ADR-0075, ADR-0171)"})] += 1
    for role, cidr in plan["prefixes"].items():
        status = "container" if plan["record_class"][role] == "prefix-only" else "active"
        counts[ensure("/api/ipam/prefixes/", {"prefix": cidr}, {"prefix": cidr, "status": status, "tags": tag,
                                                                "description": f"{role} (address plan, ADR-0075)"})] += 1
    nets = [ipaddress.ip_network(c) for c in plan["prefixes"].values()]
    for addr, x in plan["addresses"].items():
        ip = ipaddress.ip_address(addr)
        plen = max((n.prefixlen for n in nets if ip in n), default=128)
        counts[ensure("/api/ipam/ip-addresses/", {"address": addr}, {"address": f"{addr}/{plen}", "status": x["status"],
                                                                     "tags": tag, "description": x["role"]})] += 1
    print(f"seed {plan['site']}: {counts['created']} created, {counts['present']} present")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (OSError, RuntimeError) as e:
        print(f"seed failed: {e}")
        sys.exit(1)
